/// (wave 28b, D13) The test hook `CODEX_CONSULT_TEST_HEALTH_FAIL_FIRST=1` (test mode only) has been
/// used in this process.
static HEALTH_FAIL_FIRST_DONE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// (wave 9f, F78-2) Is this an id-carrying instant-429 cap-evidence row? `machine_endpoint_consults`
/// mirrors a machine record with `finished_at == when` (wall 0 < `INSTANT_429_SECS`), so a
/// burst-class quota record that carries a consult id is exactly the instant 429 the cap-pair
/// detector counts. Such a row is retained for `CAP_PAIR_RETENTION_MINUTES` and evicted last.
fn is_cap_evidence(e: &MachineEndpoint) -> bool {
    !e.consult_id.is_empty() && e.class == "quota" && e.kind == "burst"
}

/// (wave 9g, F80-1) Is this machine row what `endpoint_health` treats as a CLEARING SUCCESS - a
/// usable reply that suppresses older cap candidates (its `newest_ok`)? `machine_endpoint_consults`
/// mirrors a `class == "ok"` row as the outcome `"usable reply"`, which [`is_usable_outcome`]
/// accepts (`is_usable_outcome("usable reply")`); no other machine class yields a usable outcome, so
/// `class == "ok"` is the faithful machine-side form of that predicate.
fn is_clearing_success(e: &MachineEndpoint) -> bool {
    e.class == "ok"
}

/// A machine row's `when` as UTC, if it parses.
fn when_utc(e: &MachineEndpoint) -> Option<DateTime<Utc>> {
    DateTime::parse_from_rfc3339(&e.when)
        .ok()
        .map(|d| d.with_timezone(&Utc))
}

/// (wave 9h, F82-1 / wave 9i, F84-1) The CLEARING ANCHOR of each endpoint fingerprint: the identity
/// `(when, machine_record_key)` of EXACTLY ONE clearing-success row ([`is_clearing_success`]) - the
/// newest `when`, ties broken by the greater record key (lexicographic, so the choice is deterministic
/// across writers). The anchor is protected like cap evidence - kept for `CAP_PAIR_RETENTION_MINUTES`
/// and evicted only in the last cap tier - so evidence that arrives LATE (appended from a busy journal
/// held past the open retries, or a delayed direct retry) is still superseded on the update that merges
/// it and can never resurrect a refusal the success had cleared. Older `ok` rows AND redundant rows tied
/// on the newest `when` stay plain (tier 1), so they cannot consume the protected tier and crowd out
/// another endpoint's only clearing proof (F84-1). Computed once and reused for the supersede step,
/// retention and the cap.
fn anchor_of(
    endpoints: &[MachineEndpoint],
) -> std::collections::HashMap<String, (DateTime<Utc>, String)> {
    let mut anchors: std::collections::HashMap<String, (DateTime<Utc>, String)> =
        std::collections::HashMap::new();
    for e in endpoints {
        if is_clearing_success(e) {
            if let Some(w) = when_utc(e) {
                let key = machine_record_key(e);
                anchors
                    .entry(e.endpoint.clone())
                    .and_modify(|cur| {
                        if w > cur.0 || (w == cur.0 && key > cur.1) {
                            *cur = (w, key.clone());
                        }
                    })
                    .or_insert_with(|| (w, key.clone()));
            }
        }
    }
    anchors
}

/// (wave 9h, F82-1 / wave 9i, F84-1) Is this row the single chosen clearing anchor of its endpoint?
/// Both the `when` and the record key must match, so at most one row per endpoint is an anchor.
fn is_anchor(
    e: &MachineEndpoint,
    anchors: &std::collections::HashMap<String, (DateTime<Utc>, String)>,
) -> bool {
    is_clearing_success(e)
        && anchors
            .get(&e.endpoint)
            .is_some_and(|(w, key)| when_utc(e) == Some(*w) && machine_record_key(e) == *key)
}

/// Drop up to `drop` of the rows for which `pred` holds, OLDEST by `when` first (an unparseable `when`
/// sorts first, so it is dropped first). Returns how many still need dropping.
fn drop_oldest_matching(
    endpoints: &mut Vec<MachineEndpoint>,
    drop: usize,
    pred: impl Fn(&MachineEndpoint) -> bool,
) -> usize {
    if drop == 0 {
        return 0;
    }
    let mut cand: Vec<usize> = (0..endpoints.len())
        .filter(|&i| pred(&endpoints[i]))
        .collect();
    cand.sort_by_key(|&i| when_utc(&endpoints[i]));
    let cut: std::collections::HashSet<usize> = cand.into_iter().take(drop).collect();
    let removed = cut.len();
    let mut i = 0usize;
    endpoints.retain(|_| {
        let keep = !cut.contains(&i);
        i += 1;
        keep
    });
    drop - removed
}

/// (wave 9f, F78-2 / wave 9h, F82-1) Enforce the record cap in three tiers, protecting cap evidence
/// and the clearing anchors longest. First evict NON-protected rows (from the front, oldest first as
/// the list is built). If still over, evict cap evidence ([`is_cap_evidence`]) OLDEST FIRST by `when`.
/// Only if still over, evict the clearing anchors ([`is_anchor`]) oldest first. So an endpoint's older
/// evidence always goes before its anchor, and a lone old anchor outlives newer filler evidence -
/// without it, a success evicted here while its pair waits in a busy journal would restore the refusal
/// (F82-1). At most one row per endpoint is an anchor (wave 9i, F84-1), so redundant equal-time
/// successes are plain tier-1 rows and cannot crowd this protected tier.
fn cap_machine_endpoints(
    endpoints: &mut Vec<MachineEndpoint>,
    max: usize,
    anchors: &std::collections::HashMap<String, (DateTime<Utc>, String)>,
) {
    if endpoints.len() <= max {
        return;
    }
    let mut drop = endpoints.len() - max;
    // tier 1: non-protected rows, in list order (oldest first)
    endpoints.retain(|e| {
        if drop > 0 && !is_cap_evidence(e) && !is_anchor(e, anchors) {
            drop -= 1;
            false
        } else {
            true
        }
    });
    // tier 2: cap evidence, oldest by `when`
    drop = drop_oldest_matching(endpoints, drop, is_cap_evidence);
    // tier 3: the clearing anchors, oldest by `when`
    drop_oldest_matching(endpoints, drop, |e| is_anchor(e, anchors));
}

